contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes32 g, uint amount) public payable {
        require(address(this).balance >= amount);
        require(amount == 1 ether);

        c.lockInGuess{value: amount}(g);

        // settle() in the same block/transaction must revert:
        // the required block.number > guesses[msg.sender].block cannot hold yet.
        bool reverted;
        try c.settle() { reverted = false; } catch { reverted = true; }

        assert(reverted);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes32 g, uint amount) public payable {
        require(address(this).balance >= amount);
        require(amount == 1 ether);

        c.lockInGuess{value: amount}(g);

        // settle() cannot succeed in the same block; state stays locked.
        bool settleReverted;
        try c.settle() { settleReverted = false; } catch { settleReverted = true; }

        // Re-locking must still revert: the guess slot was not freed.
        bool relockReverted;
        try c.lockInGuess{value: amount}(g) { relockReverted = false; } catch { relockReverted = true; }

        assert(settleReverted && relockReverted);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint dummy) public {
        require(dummy >= 0);

        uint balBefore = address(c).balance;

        bool reverted;
        try c.settle() { reverted = false; } catch { reverted = true; }

        assert(reverted && address(c).balance == balBefore);
    }

    receive() external payable {}
}
